        print(f"   📍 Meta: {match['meta_file']}")

    if not force:
        if not is_current:
            print("\n⚠️  CROSS-PROJECT REMOVAL!")
            print("   This will delete the index from another project.")

        response = input(f"   ❓ Confirm removal from {location_info}? (y/N): ").strip().lower()
