    all_matches = self._find_all_matching_indexes(index_name)

    if not all_matches:
        print(f"❌ Index '{index_name}' not found in any project.")
        return False

    if len(all_matches) == 1:
        return self._remove_single_match(all_matches[0], index_name, force)
    else:
