            )
            pytest.skip("Node.js or @lmstudio/sdk not available - SDK bridge unavailable")
        else:
            assert context_length > 0
            logger.info(
                f"✓ LM Studio context length detected via SDK: {context_length} for {model_name}"
            )

    except ImportError:
